+// Pipe-only words (AGGREGATE and EXTEND) are identifiers in ordinary SQL, so
+// promote clause names only in the syntactic position immediately after `|>`.
+function markPipeClauses(tokens: Token[]): Token[] {
+  const result = tokens.map(token => ({ ...token }));
+
+  result.forEach((token, index) => {
+    if (token.type !== TokenType.PIPE) {
+      return;
+    }
+    const clause = nextNonCommentToken(result, index);
+    if (clause && pipeClauseNames.has(clause.text)) {
+      clause.type = TokenType.PIPE_CLAUSE;
+    }
+  });
+
+  result.forEach((token, index) => {
+    if (token.type !== TokenType.PIPE_CLAUSE || token.text !== 'AGGREGATE') {
+      return;
+    }
+    for (let i = index + 1; i < result.length && result[i].type !== TokenType.PIPE; i++) {
+      if (result[i].type === TokenType.RESERVED_CLAUSE && result[i].text === 'GROUP BY') {
+        result[i].type = TokenType.PIPE_GROUP_BY;
+        break;
+      }
+    }
+  });
+
+  // A pipe query must begin with FROM. Retag it only when a pipe occurs before
+  // the end of its statement or parenthesized subquery.
+  result.forEach((token, index) => {
+    if (token.type !== TokenType.RESERVED_CLAUSE || token.text !== 'FROM') {
+      return;
+    }
+    if (isLeadingFrom(result, index) && hasPipeInScope(result, index)) {
+      token.type = TokenType.PIPE_FROM;
+    }
+  });
+  return result;
+}
+
+const isComment = (token: Token) =>
+  token.type === TokenType.LINE_COMMENT || token.type === TokenType.BLOCK_COMMENT;
+
+function nextNonCommentToken(tokens: Token[], index: number): Token | undefined {
+  for (let i = index + 1; i < tokens.length; i++) {
+    if (!isComment(tokens[i])) return tokens[i];
+  }
+}
+
+function isLeadingFrom(tokens: Token[], index: number): boolean {
+  for (let i = index - 1; i >= 0; i--) {
+    const token = tokens[i];
+    if (isComment(token)) continue;
+    return token.type === TokenType.DELIMITER || token.type === TokenType.OPEN_PAREN;
+  }
+  return true;
+}
+
+function hasPipeInScope(tokens: Token[], index: number): boolean {
+  let depth = 0;
+  for (let i = index + 1; i < tokens.length; i++) {
+    const token = tokens[i];
+    if (token.type === TokenType.OPEN_PAREN) depth++;
+    if (token.type === TokenType.CLOSE_PAREN) {
+      if (depth === 0) return false;
+      depth--;
+    }
+    if (depth === 0 && token.type === TokenType.DELIMITER) return false;
+    if (depth === 0 && token.type === TokenType.PIPE) return true;
+  }
+  return false;
+}
